INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 6, 'theory', 'Quiz: Emulation, virtio and vhost');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 6, 0, 'Why is emulation of a real network card slow?', '["Its drivers are outdated", "Every driver access to a device register is an exit to the hypervisor, and a packet takes about a dozen", "Emulation doesn''t support networking", "The emulated card runs at a reduced clock speed"]', 1, 'The device registers live at addresses the hypervisor intercepts, and every access is an exit to QEMU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 6, 1, 'What does a virtio virtqueue consist of?', '["One ring and one register", "Three sockets", "A descriptor table, an available ring (guest → device) and a used ring (device → guest)", "A file and a pipe"]', 2, 'A descriptor chain describes the request buffers, while the rings carry only the numbers of the chain heads.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 6, 2, 'How does virtio reduce the number of exits?', '["It disables interrupts in the guest", "It always polls registers", "It uses one buffer at a time", "The guest puts many buffers into the queue and notifies the device once, and a busy device asks not to be rung"]', 3, 'Batching and notification suppression flags cut the number of exits by orders of magnitude.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 6, 3, 'What does vhost do?', '["It moves queue processing from the QEMU process into a host kernel thread, with notifications going through eventfd", "It encrypts the queues", "It replaces virtio with emulation", "It disables guest interrupts"]', 0, 'A guest write becomes an ioeventfd signal, and an interrupt to the guest becomes an irqfd signal, so QEMU leaves the hot path.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 6, 4, 'What is vDPA?', '["Emulation of old network cards", "A way to compress disk images", "Hardware serves the data path, while the guest sees a standard virtio device", "Device passthrough without an IOMMU"]', 2, 'The guest uses the ordinary virtio driver, so such a machine is easier to migrate than one with passthrough.');
